    <style>
    .custom-slider-wrapper {
        position: relative;
        width: 100%;
        overflow: hidden;
        display: flex;
        align-items: center;
    }
    .custom-slider-track {
        display: flex;
        transition: transform 0.6s ease;
        gap: 15px;
    }
    .slider-item {
        flex: 0 0 calc(20% - 15px);
    }
    .slider-item img {
        width: 100%;
        border-radius: 8px;
    }
    .slider-prev, .slider-next {
        background: rgba(0,0,0,0.3);
        border: none;
        color: white;
        font-size: 24px;
        padding: 10px;
        cursor: pointer;
        z-index: 10;
    }
    .slider-prev { position: absolute; left: 10px; }
    .slider-next { position: absolute; right: 10px; }
    </style>
    <script>
    document.addEventListener('DOMContentLoaded', function(){
        const wrapper = document.querySelector('.custom-slider-wrapper');
        const track = wrapper.querySelector('.custom-slider-track');
        const items = track.querySelectorAll('.slider-item');
        const prev = wrapper.querySelector('.slider-prev');
        const next = wrapper.querySelector('.slider-next');

        let index = 0;
        const visible = 5;
        const total = items.length;

        function updateSlider(){
            track.style.transform = `translateX(-${index * (100 / visible)}%)`;
        }

        next.addEventListener('click', ()=>{
            index = (index + 1) % (total - visible + 1);
            updateSlider();
        });
        prev.addEventListener('click', ()=>{
            index = (index - 1 + (total - visible + 1)) % (total - visible + 1);
            updateSlider();
        });

        setInterval(()=>{
            index = (index + 1) % (total - visible + 1);
            updateSlider();
        }, 3000);
    });
    </script>
    



