    <style>

    /* =========================================================
       SIDEBAR
    ========================================================= */

    .sidebar-accordion-fixed {

        position: fixed;
        top: 169px;
        left: 0;

        width: 190px;

        background: #ff6600;
        color: #fff;

        border-radius: 0 6px 6px 0;

        font-size: 14px;

        z-index: 9999;

        box-shadow:
            2px 2px 6px rgba(0,0,0,0.2);

        transform: translateX(-190px);

        transition:
            transform 0.3s ease;
    }


    .sidebar-accordion-fixed.show {

        transform:
            translateX(0);
    }


    /* =========================================================
       SCROLL
    ========================================================= */

    .sidebar-scroll {

        max-height:
            calc(100vh - 120px);

        overflow-y: auto;

        padding: 0;
    }


    /* =========================================================
       BOTÓN TOGGLE
    ========================================================= */

    .sidebar-toggle-btn {

        position: fixed;

        top: 169px;

        left: 0;

        background: #ff6600;

        color: #fff;

        padding: 10px 14px;

        cursor: pointer;

        font-size: 18px;

        z-index: 10000;

        border-radius:
            0 5px 5px 0;

        transition:
            left 0.3s ease;
    }


    .sidebar-accordion-fixed.show
    + .sidebar-toggle-btn {

        left: 190px;
    }


    /* =========================================================
       ACORDEÓN
    ========================================================= */

    .accordion-item {

        border-bottom:
            1px solid rgba(255,255,255,0.2);
    }


    .accordion-header {

        width: 100%;

        background: #ff6600;

        color: #fff;

        border: none;

        text-align: left;

        padding: 10px;

        font-size: 14px;

        font-weight: bold;

        cursor: pointer;

        display: flex;

        align-items: center;

        gap: 6px;
    }


    .accordion-header:hover {

        background: #e65c00;
    }


    .arrow {

        display: inline-block;

        width: 14px;

        font-weight: bold;

        user-select: none;

        transition:
            transform 0.3s ease;

        transform-origin: center;
    }


    .arrow.rotate {

        transform:
            rotate(90deg);
    }


    .accordion-content {

        display: none;

        padding: 8px;

        background: #ff8533;
    }


    .accordion-content ul {

        list-style: none;

        margin: 0;

        padding: 0;
    }


    .accordion-content li {

        margin-bottom: 7px;
    }


    .accordion-content li a {

        color: #fff;

        text-decoration: none;

        font-size: 13px;

        display: block;

        padding: 2px 0;
    }


    .accordion-content li a:hover {

        text-decoration: underline;
    }


    </style>


    <script>

    document.addEventListener(
        'DOMContentLoaded',
        function() {

            const sidebar =
                document.getElementById(
                    'sidebar-accordion-fixed'
                );

            const toggleBtn =
                document.getElementById(
                    'sidebar-toggle-btn'
                );


            // =================================================
            // ABRIR / CERRAR SIDEBAR
            // =================================================

            if (sidebar && toggleBtn) {

                toggleBtn.addEventListener(
                    'click',
                    function() {

                        sidebar.classList.toggle(
                            'show'
                        );
                    }
                );
            }


            // =================================================
            // ACORDEONES
            // =================================================

            const headers =
                document.querySelectorAll(
                    '.accordion-header'
                );


            headers.forEach(
                header => {

                    header.addEventListener(
                        'click',
                        function() {

                            // CERRAR OTROS

                            headers.forEach(
                                h => {

                                    if (h !== this) {

                                        const content =
                                            h.nextElementSibling;

                                        if (
                                            content &&
                                            content.classList.contains(
                                                'show'
                                            )
                                        ) {

                                            content.classList.remove(
                                                'show'
                                            );

                                            content.style.display =
                                                'none';

                                            const otherArrow =
                                                h.querySelector(
                                                    '.arrow'
                                                );

                                            if (otherArrow) {

                                                otherArrow.classList.remove(
                                                    'rotate'
                                                );
                                            }
                                        }
                                    }
                                }
                            );


                            // ABRIR / CERRAR ACTUAL

                            const content =
                                this.nextElementSibling;

                            const arrow =
                                this.querySelector(
                                    '.arrow'
                                );


                            if (
                                content.classList.contains(
                                    'show'
                                )
                            ) {

                                content.classList.remove(
                                    'show'
                                );

                                content.style.display =
                                    'none';

                                arrow.classList.remove(
                                    'rotate'
                                );

                            } else {

                                content.classList.add(
                                    'show'
                                );

                                content.style.display =
                                    'block';

                                arrow.classList.add(
                                    'rotate'
                                );
                            }

                        }
                    );
                }
            );

        }
    );

    </script>

